<?php require_once __DIR__.'/config/config.php';$cart=$_SESSION['cart']??[];$items=[];$total=0;foreach($cart as $id=>$c){$s=$pdo->prepare('SELECT * FROM products WHERE id=? AND active=1');$s->execute([$id]);if($p=$s->fetch()){$p['qty']=(int)$c['qty'];$p['line']=($p['sale_price']?:$p['price'])*$p['qty'];$total+=$p['line'];$items[]=$p;}}if(!$items)go('cart.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$email=trim($_POST['email']??'');$address=trim($_POST['address']??'');$city=trim($_POST['city']??'');if(!$name||!$phone||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$address||!$city){$error='Please complete all required fields.';}else{try{$pdo->beginTransaction();foreach($items as $p){$u=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=? AND stock>=?');$u->execute([$p['qty'],$p['id'],$p['qty']]);if(!$u->rowCount())throw new Exception('Stock changed. Please review your cart.');}$c=$pdo->prepare('INSERT INTO customers(name,phone,email,address,city) VALUES(?,?,?,?,?)');$c->execute([$name,$phone,$email,$address,$city]);$customer=$pdo->lastInsertId();$oid='WE'.date('ymd').strtoupper(bin2hex(random_bytes(3)));$o=$pdo->prepare("INSERT INTO orders(order_code,customer_id,total,shipping,payment_method,status) VALUES(?,?,?,0,'Cash on Delivery','New Order')");$o->execute([$oid,$customer,$total]);$orderId=$pdo->lastInsertId();$oi=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,quantity,unit_price) VALUES(?,?,?,?,?)');foreach($items as $p)$oi->execute([$orderId,$p['id'],$p['name'],$p['qty'],$p['sale_price']?:$p['price']]);$h=$pdo->prepare('INSERT INTO order_status_history(order_id,status,note) VALUES(?,?,?)');$h->execute([$orderId,'New Order','Order placed']);$pdo->commit();unset($_SESSION['cart']);$_SESSION['last_order']=$oid;go('confirmation.php?order='.urlencode($oid));}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}}require 'includes/header.php';?><section class="section"><div class="container"><h1 style="font-family:'Playfair Display'">Checkout</h1><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="row g-4"><div class="col-lg-7"><form method="post" class="admin-card"><?=csrf_field()?><label class="form-label">Full name</label><input class="form-control mb-3" name="name" required><label class="form-label">Phone</label><input class="form-control mb-3" name="phone" required><label class="form-label">Email</label><input class="form-control mb-3" type="email" name="email" required><label class="form-label">Shipping address</label><textarea class="form-control mb-3" name="address" required></textarea><label class="form-label">City</label><input class="form-control mb-3" name="city" required><label class="form-label">Payment</label><div class="form-check"><input class="form-check-input" type="radio" checked disabled><label class="form-check-label">Cash on Delivery</label></div><small class="text-secondary">Online payment is not configured yet.</small><button class="btn btn-gold w-100 mt-4">Place Order</button></form></div><div class="col-lg-5"><div class="admin-card"><h4>Order Summary</h4><?php foreach($items as $p):?><p><?=e($p['name'])?> × <?=$p['qty']?> <b class="float-end"><?=money($p['line'])?></b></p><?php endforeach;?><hr><h5>Total <b class="float-end"><?=money($total)?></b></h5></div></div></div></div></section><?php require 'includes/footer.php';?>